 "content": "from collections import Counter


def transform(grid):
    """Collapse uniform nonzero separator bands to one cell per region."""
    h, w = len(grid), len(grid[0])

    def separator_lines(lines):
        found = []
        for i, line in enumerate(lines):
            counts = Counter(line)
            color, count = counts.most_common(1)[0]
            if color != 0 and count / len(line) >= 0.70:
                found.append(i)
        return found

    rows = separator_lines(grid)
    cols = separator_lines([[grid[r][c] for r in range(h)] for c in range(w)])

    def representatives(length, separators):
        selected = []
        start = 0
        for pos in separators:
            if start < pos:
                selected.append(start)
            selected.append(pos)
            start = pos + 1
        if start < length:
            selected.append(start)
        return selected

    rr = representatives(h, rows)
    cc = representatives(w, cols)
    return [[grid[r][c] for c in cc] for r in rr]
